<template>
  <div>
    <!-- 搜索和新增按钮 -->
    <el-row :gutter="20" style="margin-bottom: 20px;">
      <el-col :span="12">
        <el-input v-model="searchQuery" placeholder="搜索商品名称" @keyup.enter="handleSearch" />
      </el-col>
      <el-col :span="12" style="text-align: right;">
        <el-button type="primary" @click="handleAdd">新增商品</el-button>
      </el-col>
    </el-row>

    <!-- 商品表格 -->
    <el-table :data="productList" v-loading="loading" border style="width: 100%">
      <el-table-column prop="id" label="ID" width="80" />
      <el-table-column prop="name" label="名称" />
      <el-table-column prop="price" label="价格" />
      <el-table-column prop="stock" label="库存" />
      <el-table-column label="操作" width="200">
        <!-- 使用 v-slot 替代 slot-scope -->
        <template #default="scope">
          <el-button size="mini" @click="handleEdit(scope.row)">编辑</el-button>
          <el-button size="mini" type="danger" @click="handleDelete(scope.row.id)">删除</el-button>
        </template>
      </el-table-column>
    </el-table>

    <!-- 分页 -->
    <el-pagination
      @size-change="handleSizeChange"
      @current-change="handleCurrentChange"
      :current-page="page"
      :page-sizes="[10, 20, 50]"
      :page-size="pageSize"
      layout="total, sizes, prev, pager, next, jumper"
      :total="total"
      style="margin-top: 20px;"
    />

    <!-- 新增/编辑对话框 -->
    <!-- .sync 仍可用，添加忽略注释避免 ESLint 报错 -->
    <!-- eslint-disable-next-line vue/no-deprecated-v-bind-sync -->
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="500px">
      <el-form :model="form" :rules="formRules" ref="form" label-width="80px">
        <el-form-item label="名称" prop="name">
          <el-input v-model="form.name" />
        </el-form-item>
        <el-form-item label="价格" prop="price">
          <el-input-number v-model="form.price" :precision="2" :min="0" />
        </el-form-item>
        <el-form-item label="库存" prop="stock">
          <el-input-number v-model="form.stock" :min="0" />
        </el-form-item>
      </el-form>
      <!-- 使用 #footer 替代 slot="footer" -->
      <template #footer>
        <span>
          <el-button @click="dialogVisible = false">取消</el-button>
          <el-button type="primary" @click="saveProduct">保存</el-button>
        </span>
      </template>
    </el-dialog>
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

export default {
  name: 'ProductManagement',
  data() {
    return {
      searchQuery: '',
      page: 1,
      pageSize: 10,
      dialogVisible: false,
      editId: null,
      form: { name: '', price: 0, stock: 0 },
      formRules: {
        name: [{ required: true, message: '请输入商品名称', trigger: 'blur' }],
        price: [{ required: true, type: 'number', message: '请输入价格', trigger: 'blur' }]
      }
    }
  },
  computed: {
    ...mapState('product', ['list', 'total', 'loading']),
    productList() {
      return this.list
    },
    dialogTitle() {
      return this.editId ? '编辑商品' : '新增商品'
    }
  },
  created() {
    this.fetchData()
  },
  methods: {
    ...mapActions('product', ['fetchProducts', 'addProduct', 'updateProduct', 'deleteProduct']),
    fetchData() {
      const params = {
        page: this.page,
        pageSize: this.pageSize,
        keyword: this.searchQuery
      }
      this.fetchProducts(params)
    },
    handleSearch() {
      this.page = 1
      this.fetchData()
    },
    handleSizeChange(val) {
      this.pageSize = val
      this.page = 1
      this.fetchData()
    },
    handleCurrentChange(val) {
      this.page = val
      this.fetchData()
    },
    handleAdd() {
      this.editId = null
      this.form = { name: '', price: 0, stock: 0 }
      this.dialogVisible = true
    },
    handleEdit(row) {
      this.editId = row.id
      this.form = { ...row }
      this.dialogVisible = true
    },
    async handleDelete(id) {
      await this.$confirm('确认删除该商品吗？', '提示', { type: 'warning' })
      await this.deleteProduct(id)
      this.$message.success('删除成功')
    },
    saveProduct() {
      this.$refs.form.validate(async valid => {
        if (valid) {
          if (this.editId) {
            await this.updateProduct({ id: this.editId, data: this.form })
          } else {
            await this.addProduct(this.form)
          }
          this.$message.success('保存成功')
          this.dialogVisible = false
          this.fetchData()
        }
      })
    }
  }
}
</script>